repoLayout:
sanad/
├─ README.md
├─ CONTRIBUTING.ar.md              # Abgabe-Protokoll fuer die Ikhwa, arabisch
├─ docker-compose.yml              # lokal: postgres18 + pgvector + pg_search + pgmq, redis, minio
├─ Makefile                        # make dev | make eval | make reindex | make seed
├─ turbo.json  pnpm-workspace.yaml
├─ apps/
│  ├─ web/                         # Next.js 16.4, App Router, cacheComponents: true
│  │  ├─ app/[locale]/(library)/{page.tsx, v/[videoId]/page.tsx, topic/[slug]/page.tsx}
│  │  ├─ app/[locale]/(ask)/ask/page.tsx
│  │  ├─ app/[locale]/(submit)/submit/page.tsx          # presigned upload, Pflichtfelder
│  │  ├─ app/[locale]/(admin)/review/{segment,translation,answer}/page.tsx
│  │  ├─ components/{Player,TranscriptPane,SourceCard,CitationAnchor,AbstainNotice,AiDisclosure}
│  │  ├─ messages/{ar.json,de.json,en.json}
│  │  └─ styles/fonts/            # Noto Naskh Arabic + IBM Plex Sans Arabic, subgesetzt
│  └─ admin-cli/                   # Node-CLI: approve, retract, invalidate, export
├─ services/
│  ├─ api/                         # FastAPI — die einzige API
│  │  ├─ sanad_api/routers/{ask.py,library.py,ingest.py,review.py,eval.py,internal.py}
│  │  ├─ sanad_api/retrieval/{normalize.py,expand.py,hybrid.py,rrf.py,dedup.py,rerank.py,parent.py,gate.py}
│  │  ├─ sanad_api/answer/{prompt.py,blocks.py,synthesize.py,verify.py,stream.py,abstain.py}
│  │  ├─ sanad_api/llm/{gateway.py,anthropic.py,gemini.py}   # Rollen: synthesize | cheap_task | verify
│  │  ├─ sanad_api/cache/{exact.py,semantic.py,precompute.py,invalidate.py}
│  │  └─ pyproject.toml            # uv
│  ├─ worker/                      # pgmq-Consumer, eine Queue je Pipeline-Stufe
│  │  └─ sanad_worker/stages/{intake.py,transcode.py,asr.py,align.py,segment.py,quote_link.py,
│  │                            dedup.py,translate.py,qa_translate.py,chunk.py,contextualize.py,
│  │                            embed.py,publish.py}
│  └─ eval/                        # Goldset-Runner, Shadow-Replay, Report-Generator
│     └─ sanad_eval/{goldset.py,metrics.py,run.py,shadow.py,report.py}
├─ packages/
│  ├─ api-client/                  # generiert aus openapi.json via @hey-api/openapi-ts, committed
│  ├─ arabic/                      # normalize_ar (Python + SQL + TS, EINE Referenzimplementierung + Testvektoren)
│  └─ ui/
├─ db/
│  ├─ migrations/
│  ├─ functions/{normalize_ar.sql,rrf_fuse.sql,hybrid_search.sql}
│  └─ seeds/{scholars.yaml,scholar_aliases.yaml,topics.yaml,glossary.yaml}
├─ data/
│  ├─ quran/                       # Tanzil, CC BY 3.0, lokal gespiegelt
│  ├─ hadith/                      # fawazahmed0/hadith-api, Unlicense
│  └─ goldset/{queries.yaml,judgments.yaml}
├─ export/                         # naechtlicher JSONL-Export: transcripts/, translations/, metadata/
├─ infra/
│  ├─ coolify/{app.yml,worker.yml,db.yml}
│  ├─ pgbackrest/
│  └─ runpod/{embed_job.py,rerank_server.py}
└─ .github/workflows/{ci.yml,eval-nightly.yml,openapi-drift.yml}
